INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('5fa8cd0a-10f5-4f33-b34b-8a36c9c4b2d6', 'Ethical Sourcing & Conflict-Free Diamonds', 'sustainability', '{"heading":"Ethical Sourcing & Conflict-Free Diamonds","subheading":"Our unwavering commitment to ethical sourcing, Kimberley Process compliance, and environmental stewardship.","introduction":"AethelCarats strictly enforces a zero-tolerance policy against conflict diamonds. Every natural diamond is 100% Kimberley Process certified.","conflictFreePolicy":"We only partner with vetted sightholders and diamond cutters who adhere strictly to international human rights and labor standards.","diamondSourcing":"Our natural diamonds originate from certified mines in Canada, Botswana, Namibia, and Australia.","labGrownDiamonds":"We offer climate-neutral lab-grown diamonds created using 100% renewable solar and hydro energy in state-of-the-art reactors.","naturalDiamonds":"Our natural diamonds are ethically mined, supporting local community development, education, and healthcare initiatives.","responsibleManufacturing":"Our Fifth Avenue atelier utilizes 100% recycled 18K gold and silver to minimize environmental mining impact.","environmentalInformation":"Zero-waste luxury packaging crafted from FSC-certified sustainable timber and organic velvet.","certifications":"Kimberley Process Compliant, Responsible Jewellery Council (RJC) Certified, GIA & IGI Verified.","additionalInformation":"Transparency is our guarantee. Every stone over 0.50ct includes a laser-inscribed girdle number."}', '{"heading":"Ethical Sourcing & Conflict-Free Diamonds","subheading":"Our unwavering commitment to ethical sourcing, Kimberley Process compliance, and environmental stewardship.","introduction":"AethelCarats strictly enforces a zero-tolerance policy against conflict diamonds. Every natural diamond is 100% Kimberley Process certified.","conflictFreePolicy":"We only partner with vetted sightholders and diamond cutters who adhere strictly to international human rights and labor standards.","diamondSourcing":"Our natural diamonds originate from certified mines in Canada, Botswana, Namibia, and Australia.","labGrownDiamonds":"We offer climate-neutral lab-grown diamonds created using 100% renewable solar and hydro energy in state-of-the-art reactors.","naturalDiamonds":"Our natural diamonds are ethically mined, supporting local community development, education, and healthcare initiatives.","responsibleManufacturing":"Our Fifth Avenue atelier utilizes 100% recycled 18K gold and silver to minimize environmental mining impact.","environmentalInformation":"Zero-waste luxury packaging crafted from FSC-certified sustainable timber and organic velvet.","certifications":"Kimberley Process Compliant, Responsible Jewellery Council (RJC) Certified, GIA & IGI Verified.","additionalInformation":"Transparency is our guarantee. Every stone over 0.50ct includes a laser-inscribed girdle number."}', 'PUBLISHED', '2026-08-10 05:22:28.018', 'System Seed', NULL, '2026-08-10 05:22:28.019', '2026-08-10 08:53:48.356');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('18b9d8d3-e22f-475f-bbc8-65e2f557d11d', 'Diamond Price Match Guarantee', 'price-match', '{"heading":"Diamond Price Match Guarantee","subheading":"If you find an identical GIA or IGI certified diamond at a lower price, AethelCarats will match or beat the price.","introduction":"We are committed to delivering the highest value in fine jewellery. Our global direct diamond sourcing allows us to offer unbeatable prices.","eligibility":"The diamond must be currently available for purchase on a US or international retailer website.","requirements":"Must have exact matching 4Cs (Carat, Cut, Color, Clarity), fluorescence, polish, symmetry, and lab certification (GIA/IGI).","excludedProducts":"Promotional auctions, clearance liquidations, secondary market pawn inventory, and uncertified stones.","howItWorks":"Submit the competitor diamond URL or certificate number to concierge@aethelcarats.com.","verificationProcess":"Our gemologists verify the competitor diamond availability and grading match within 4 business hours.","terms":"Price match applies to the final diamond cost before taxes and shipping.","buttonText":"Submit Price Match Request","buttonUrl":"/contact-us?subject=Price+Match"}', '{"heading":"Diamond Price Match Guarantee","subheading":"If you find an identical GIA or IGI certified diamond at a lower price, AethelCarats will match or beat the price.","introduction":"We are committed to delivering the highest value in fine jewellery. Our global direct diamond sourcing allows us to offer unbeatable prices.","eligibility":"The diamond must be currently available for purchase on a US or international retailer website.","requirements":"Must have exact matching 4Cs (Carat, Cut, Color, Clarity), fluorescence, polish, symmetry, and lab certification (GIA/IGI).","excludedProducts":"Promotional auctions, clearance liquidations, secondary market pawn inventory, and uncertified stones.","howItWorks":"Submit the competitor diamond URL or certificate number to concierge@aethelcarats.com.","verificationProcess":"Our gemologists verify the competitor diamond availability and grading match within 4 business hours.","terms":"Price match applies to the final diamond cost before taxes and shipping.","buttonText":"Submit Price Match Request","buttonUrl":"/contact-us?subject=Price+Match"}', 'PUBLISHED', '2026-08-10 05:22:28.231', 'System Seed', NULL, '2026-08-10 05:22:28.232', '2026-08-10 08:53:48.568');
