INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('72522731-f301-4b79-a1b0-539c43e6aec7', 'Jewellery Insurance & Protection', 'insurance', '{"heading":"Jewellery Insurance & Protection","subheading":"Protect your valuable fine jewellery against accidental loss, theft, and damage with specialized coverage.","introduction":"Your fine jewellery is an investment in beauty and memory. We partner with leading appraisal networks and insurers to safeguard your collection.","insuranceInformation":"We provide complimentary certified gemological appraisal certificates for all purchases over $1,000.","coverage":"Worldwide protection against mysterious disappearance, loss, theft, damage, and stone chipping.","eligibility":"All natural diamonds, lab-grown diamonds, high jewellery, and custom engagement rings.","claims":"Fast claims processing with direct replacement through AethelCarats Atelier.","importantInformation":"Most standard homeowners policies cap jewellery coverage. Dedicated jewellery insurance guarantees full replacement value.","buttonText":"Download Complimentary Appraisal","buttonUrl":"/account#appraisals"}', '{"heading":"Jewellery Insurance & Protection","subheading":"Protect your valuable fine jewellery against accidental loss, theft, and damage with specialized coverage.","introduction":"Your fine jewellery is an investment in beauty and memory. We partner with leading appraisal networks and insurers to safeguard your collection.","insuranceInformation":"We provide complimentary certified gemological appraisal certificates for all purchases over $1,000.","coverage":"Worldwide protection against mysterious disappearance, loss, theft, damage, and stone chipping.","eligibility":"All natural diamonds, lab-grown diamonds, high jewellery, and custom engagement rings.","claims":"Fast claims processing with direct replacement through AethelCarats Atelier.","importantInformation":"Most standard homeowners policies cap jewellery coverage. Dedicated jewellery insurance guarantees full replacement value.","buttonText":"Download Complimentary Appraisal","buttonUrl":"/account#appraisals"}', 'PUBLISHED', '2026-08-10 05:22:28.656', 'System Seed', NULL, '2026-08-10 05:22:28.657', '2026-08-10 08:53:48.994');
