INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('f8261e99-776f-4733-abca-b58c133267d4', 'Privacy Policy', 'privacy-policy', '{"heading":"Privacy Policy","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Information We Collect</h2>\\\\n      <p>AethelCarats collects personal information necessary to fulfill orders, process payments, and provide personalized client service. This includes contact details, billing/shipping addresses, and payment information.</p>\\\\n      <h2>2. How We Use Your Information</h2>\\\\n      <p>Your information is strictly used for order processing, logistics insurance, diamond certificate issuance, and direct concierge communication. We never sell or share client data with unauthorized third parties.</p>\\\\n      <h2>3. Data Protection & Security</h2>\\\\n      <p>We implement bank-grade 256-bit SSL encryption and strict access controls to safeguard your financial and personal data.</p>\\\\n      <h2>4. Cookies & Analytics</h2>\\\\n      <p>Our website utilizes necessary cookies to enhance user experience, preserve shopping bag items, and measure anonymous web traffic.</p>\\\\n      <h2>5. Your Rights</h2>\\\\n      <p>You have the right to request access to, update, or permanently delete your personal account data by contacting concierge@aethelcarats.com.</p>\\\\n    "}', '{"heading":"Privacy Policy","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Information We Collect</h2>\\\\n      <p>AethelCarats collects personal information necessary to fulfill orders, process payments, and provide personalized client service. This includes contact details, billing/shipping addresses, and payment information.</p>\\\\n      <h2>2. How We Use Your Information</h2>\\\\n      <p>Your information is strictly used for order processing, logistics insurance, diamond certificate issuance, and direct concierge communication. We never sell or share client data with unauthorized third parties.</p>\\\\n      <h2>3. Data Protection & Security</h2>\\\\n      <p>We implement bank-grade 256-bit SSL encryption and strict access controls to safeguard your financial and personal data.</p>\\\\n      <h2>4. Cookies & Analytics</h2>\\\\n      <p>Our website utilizes necessary cookies to enhance user experience, preserve shopping bag items, and measure anonymous web traffic.</p>\\\\n      <h2>5. Your Rights</h2>\\\\n      <p>You have the right to request access to, update, or permanently delete your personal account data by contacting concierge@aethelcarats.com.</p>\\\\n    "}', 'PUBLISHED', '2026-08-10 05:22:31.814', 'System Seed', NULL, '2026-08-10 05:22:31.815', '2026-08-10 08:53:51.96');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('edc78291-d42d-4c3b-bea0-3db4fddffdca', 'Billing Terms & Conditions', 'billing-terms-conditions', '{"heading":"Billing Terms & Conditions","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Payment Methods Accepted</h2>\\\\n      <p>We accept major credit cards (Visa, MasterCard, American Express), Bank Wire Transfer, PayPal, and approved financing options.</p>\\\\n      <h2>2. Wire Transfer Discount</h2>\\\\n      <p>Orders paid via Bank Wire Transfer receive a 1.5% discount automatically applied at checkout.</p>\\\\n      <h2>3. Security & Fraud Verification</h2>\\\\n      <p>High-value diamond orders over $5,000 may require additional identity verification or bank wire confirmation prior to dispatch.</p>\\\\n    "}', '{"heading":"Billing Terms & Conditions","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Payment Methods Accepted</h2>\\\\n      <p>We accept major credit cards (Visa, MasterCard, American Express), Bank Wire Transfer, PayPal, and approved financing options.</p>\\\\n      <h2>2. Wire Transfer Discount</h2>\\\\n      <p>Orders paid via Bank Wire Transfer receive a 1.5% discount automatically applied at checkout.</p>\\\\n      <h2>3. Security & Fraud Verification</h2>\\\\n      <p>High-value diamond orders over $5,000 may require additional identity verification or bank wire confirmation prior to dispatch.</p>\\\\n    "}', 'PUBLISHED', '2026-08-10 05:22:32.237', 'System Seed', NULL, '2026-08-10 05:22:32.238', '2026-08-10 08:53:52.387');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('5375cead-5e7d-43de-859a-c17a7d8e3941', 'Jewellery Care & Cleaning Guide', 'jewellery-care', '{"heading":"Jewellery Care & Cleaning Guide","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Platinum & Gold Care</h2>\\\\n      <p>Clean your solid gold and platinum jewellery in warm water mixed with mild dish soap. Gently scrub with a soft-bristled toothbrush to remove oils and lotion residue.</p>\\\\n      <h2>2. Diamond Cleaning</h2>\\\\n      <p>Diamonds attract natural body oils. Soak your diamond rings weekly in warm soapy water and rinse under warm water.</p>\\\\n      <h2>3. Storage Advice</h2>\\\\n      <p>Store individual pieces in your AethelCarats velvet pouch or soft-lined box to prevent stones from scratching each other.</p>\\\\n      <h2>4. Professional Inspection</h2>\\\\n      <p>We recommend bringing or sending your diamond jewellery for complimentary annual professional inspection and ultrasonic cleaning.</p>\\\\n    "}', '{"heading":"Jewellery Care & Cleaning Guide","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Platinum & Gold Care</h2>\\\\n      <p>Clean your solid gold and platinum jewellery in warm water mixed with mild dish soap. Gently scrub with a soft-bristled toothbrush to remove oils and lotion residue.</p>\\\\n      <h2>2. Diamond Cleaning</h2>\\\\n      <p>Diamonds attract natural body oils. Soak your diamond rings weekly in warm soapy water and rinse under warm water.</p>\\\\n      <h2>3. Storage Advice</h2>\\\\n      <p>Store individual pieces in your AethelCarats velvet pouch or soft-lined box to prevent stones from scratching each other.</p>\\\\n      <h2>4. Professional Inspection</h2>\\\\n      <p>We recommend bringing or sending your diamond jewellery for complimentary annual professional inspection and ultrasonic cleaning.</p>\\\\n    "}', 'PUBLISHED', '2026-08-10 05:22:32.448', 'System Seed', NULL, '2026-08-10 05:22:32.45', '2026-08-10 08:53:52.599');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('60ef2ba5-200c-409c-9cc1-9d233506053a', 'Promotional Terms & Sale Exclusions', 'sale-exclusions', '{"heading":"Promotional Terms & Sale Exclusions","subheading":"Important information regarding promotional codes, discounts, and site-wide sales.","introduction":"Unless explicitly stated otherwise, promotional codes and site-wide discount offers are subject to standard atelier terms.","exclusionRules":"Promotional codes cannot be combined with price matches, finance plans, or other discount codes.","excludedProducts":"Loose certified diamonds, custom CAD commissions, special order high jewellery, and gift cards.","excludedCategories":"Loose Diamond Vault, Bespoke Custom Services.","importantNotes":"Discounts apply strictly to setting prices and ready-to-wear fine jewellery unless specified.","buttonText":"Contact Concierge","buttonUrl":"/contact-us"}', '{"heading":"Promotional Terms & Sale Exclusions","subheading":"Important information regarding promotional codes, discounts, and site-wide sales.","introduction":"Unless explicitly stated otherwise, promotional codes and site-wide discount offers are subject to standard atelier terms.","exclusionRules":"Promotional codes cannot be combined with price matches, finance plans, or other discount codes.","excludedProducts":"Loose certified diamonds, custom CAD commissions, special order high jewellery, and gift cards.","excludedCategories":"Loose Diamond Vault, Bespoke Custom Services.","importantNotes":"Discounts apply strictly to setting prices and ready-to-wear fine jewellery unless specified.","buttonText":"Contact Concierge","buttonUrl":"/contact-us"}', 'PUBLISHED', '2026-08-10 05:22:29.688', 'System Seed', NULL, '2026-08-10 05:22:29.689', '2026-08-10 08:53:49.842');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('8a75f4c5-2b97-487d-a75b-19dfc2b32c4f', 'Bespoke Custom Jewellery & 3D CAD Design', 'custom-jewellery', '{"heading":"Bespoke Custom Jewellery & 3D CAD Design","subheading":"Transform your vision into a one-of-a-kind heirloom piece created specifically for you.","introduction":"Our custom design service allows you to bring your dream ring, necklace, or earring design to life with 3D digital renderings and master goldsmith craftsmanship.","step1Heading":"1. Vision & Diamond Selection","step1Description":"Share your ideas, sketches, or inspiration photos with our lead CAD designers and select your ideal loose diamond.","step2Heading":"2. 3D Digital CAD Rendering","step2Description":"Receive detailed 360-degree photorealistic 3D CAD renders showing exact proportions, dimensions, and prong placement.","step3Heading":"3. Wax Model & Casting","step3Description":"Upon your approval, a high-resolution 3D wax model is printed and cast in solid 18K gold or platinum.","step4Heading":"4. Setting & Hand Finishing","step4Description":"Our master setters set your diamonds under microscopes and polish the piece to high-jewellery perfection.","customInfo":"Total custom lead time is typically 2-3 weeks from initial CAD approval.","fileUploadInstructions":"Upload JPEG, PNG, CAD (.3dm, .stp), or PDF files up to 25MB.","supportedFileTypes":"PNG, JPG, PDF, STEP, 3DM, DWG","expectedResponseTime":"CAD quotes and preliminary sketches provided within 24 hours.","buttonText":"Start Custom CAD Inquiry","buttonUrl":"/custom-jewellery#form"}', '{"heading":"Bespoke Custom Jewellery & 3D CAD Design","subheading":"Transform your vision into a one-of-a-kind heirloom piece created specifically for you.","introduction":"Our custom design service allows you to bring your dream ring, necklace, or earring design to life with 3D digital renderings and master goldsmith craftsmanship.","step1Heading":"1. Vision & Diamond Selection","step1Description":"Share your ideas, sketches, or inspiration photos with our lead CAD designers and select your ideal loose diamond.","step2Heading":"2. 3D Digital CAD Rendering","step2Description":"Receive detailed 360-degree photorealistic 3D CAD renders showing exact proportions, dimensions, and prong placement.","step3Heading":"3. Wax Model & Casting","step3Description":"Upon your approval, a high-resolution 3D wax model is printed and cast in solid 18K gold or platinum.","step4Heading":"4. Setting & Hand Finishing","step4Description":"Our master setters set your diamonds under microscopes and polish the piece to high-jewellery perfection.","customInfo":"Total custom lead time is typically 2-3 weeks from initial CAD approval.","fileUploadInstructions":"Upload JPEG, PNG, CAD (.3dm, .stp), or PDF files up to 25MB.","supportedFileTypes":"PNG, JPG, PDF, STEP, 3DM, DWG","expectedResponseTime":"CAD quotes and preliminary sketches provided within 24 hours.","buttonText":"Start Custom CAD Inquiry","buttonUrl":"/custom-jewellery#form"}', 'PUBLISHED', '2026-08-10 05:22:29.899', 'System Seed', NULL, '2026-08-10 05:22:29.9', '2026-08-10 08:53:50.054');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('52206ddb-36af-4926-b850-39c490c35023', 'Welcome to Your AethelCarats Atelier Account', 'account', '{"title":"Customer Account Portal","heading":"Welcome to Your AethelCarats Atelier Account","introduction":"View your order history, active CAD custom commissions, appraisals, and saved wishlist items.","loginText":"Sign in to access your personal concierge portal and track your shipments.","registerText":"Create an account to enjoy personalized diamond recommendations and expedited checkout.","accountHelpText":"Need assistance with your account? Contact our client service team 24/7.","supportInformation":"Concierge Direct: +91 79902 78892 | concierge@aethelcarats.com"}', '{"title":"Customer Account Portal","heading":"Welcome to Your AethelCarats Atelier Account","introduction":"View your order history, active CAD custom commissions, appraisals, and saved wishlist items.","loginText":"Sign in to access your personal concierge portal and track your shipments.","registerText":"Create an account to enjoy personalized diamond recommendations and expedited checkout.","accountHelpText":"Need assistance with your account? Contact our client service team 24/7.","supportInformation":"Concierge Direct: +91 79902 78892 | concierge@aethelcarats.com"}', 'PUBLISHED', '2026-08-10 05:22:31.601', 'System Seed', NULL, '2026-08-10 05:22:31.602', '2026-08-10 08:53:51.748');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('37bcf944-f675-4245-bd41-358bd55a0f03', 'AethelCarats Lifetime Warranty', 'lifetime-warranty', '{"heading":"AethelCarats Lifetime Warranty","subheading":"Every fine jewellery piece is backed by our comprehensive lifetime craftsmanship guarantee.","introduction":"We stand behind the quality and craftsmanship of every piece we create. Your jewellery is guaranteed against manufacturing defects for life.","coverage":"Covers prong tightening, diamond inspection, ultrasonic cleaning, steam polishing, and manufacturing defect repairs.","eligibility":"Applies to all authentic AethelCarats rings, necklaces, bracelets, earrings, and custom CAD creations.","whatsIncluded":"Free lifetime annual inspection, prong re-tipping, rhodium re-plating for white gold, and deep cleaning.","whatsExcluded":"Normal wear and tear, trauma damage, accidental loss, theft, or repairs conducted by third-party jewelers.","claimProcess":"Bring your item to our Fifth Avenue atelier or ship it using our insured concierge shipping program.","warrantyDuration":"Lifetime coverage for the original purchaser.","importantInformation":"Third-party alterations void the warranty. Annual inspection recommended to maintain stone security.","buttonText":"Schedule Maintenance Inspection","buttonUrl":"/contact-us#inspection"}', '{"heading":"AethelCarats Lifetime Warranty","subheading":"Every fine jewellery piece is backed by our comprehensive lifetime craftsmanship guarantee.","introduction":"We stand behind the quality and craftsmanship of every piece we create. Your jewellery is guaranteed against manufacturing defects for life.","coverage":"Covers prong tightening, diamond inspection, ultrasonic cleaning, steam polishing, and manufacturing defect repairs.","eligibility":"Applies to all authentic AethelCarats rings, necklaces, bracelets, earrings, and custom CAD creations.","whatsIncluded":"Free lifetime annual inspection, prong re-tipping, rhodium re-plating for white gold, and deep cleaning.","whatsExcluded":"Normal wear and tear, trauma damage, accidental loss, theft, or repairs conducted by third-party jewelers.","claimProcess":"Bring your item to our Fifth Avenue atelier or ship it using our insured concierge shipping program.","warrantyDuration":"Lifetime coverage for the original purchaser.","importantInformation":"Third-party alterations void the warranty. Annual inspection recommended to maintain stone security.","buttonText":"Schedule Maintenance Inspection","buttonUrl":"/contact-us#inspection"}', 'PUBLISHED', '2026-08-10 05:22:28.444', 'System Seed', NULL, '2026-08-10 05:22:28.445', '2026-08-10 08:53:48.781');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('5f84eef6-502d-4e06-9c40-bcce5de2e1bc', 'Contact AethelCarats Concierge', 'contact-us', '{"heading":"Contact AethelCarats Concierge","subheading":"Our dedicated high-jewellery advisors are available to assist you with bespoke commissions, diamond sourcing, and order inquiries.","customerCareHeading":"AethelCarats Atelier Customer Care","customerCareDescription":"Experience our white-glove concierge service. Reach out via phone, WhatsApp, email, or schedule an in-person private appointment.","phone":"+91 79902 78892","phoneLabel":"Client Concierge Direct","businessHours":"Monday – Saturday: 9:00 AM – 7:00 PM EST","email":"contact@aethelcarats.com","emailLabel":"Direct Email Assistance","responseTime":"Guaranteed response within 2 business hours","address":"740 Fifth Avenue, Suite 1800, New York, NY 10019","locationLabel":"Fifth Avenue Flagship Atelier","appointmentDescription":"Private showroom consultations available by appointment only.","formHeading":"Send a Private Inquiry","formDescription":"Please complete the form below and an Atelier specialist will contact you promptly.","enquiryTypes":[{"id":"1","name":"Diamond Sourcing & Vault Inquiry","isEnabled":true},{"id":"2","name":"Bespoke Custom CAD Design","isEnabled":true},{"id":"3","name":"High Jewellery Orders","isEnabled":true},{"id":"4","name":"Private Showroom Appointment","isEnabled":true},{"id":"5","name":"Wholesale & B2B Inquiries","isEnabled":true},{"id":"6","name":"General Concierge Question","isEnabled":true}],"formFields":[{"id":"firstName","label":"First Name","required":true,"isEnabled":true},{"id":"lastName","label":"Last Name","required":true,"isEnabled":true},{"id":"email","label":"Email Address","required":true,"isEnabled":true},{"id":"phone","label":"Phone / WhatsApp","required":false,"isEnabled":true},{"id":"enquiryType","la