INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('114bf1d1-9032-46dc-a17f-fa139c2b39a8', 'Returns & Refund Policy', 'returns-refunds', '{"heading":"Returns & Refund Policy","subheading":"We offer a complimentary 15-day return policy on all non-customized fine jewellery and loose diamonds.","introduction":"At AethelCarats, your complete satisfaction is paramount. If for any reason you are not completely enchanted with your purchase, you may return it within 15 days of receipt.","returnEligibility":"Items must be returned in original, unworn condition with all original certification documents, security tags intact, and luxury box packaging.","returnWindow":"15 Days from date of delivery","nonReturnableItems":"Custom CAD bespoke jewellery, engraved items, altered ring sizes beyond standard range, and damaged items.","returnProcess":"Contact concierge@aethelcarats.com to receive a fully insured prepaid FedEx shipping label and Return Authorization (RA) number.","inspectionProcess":"Every returned gemstone and diamond undergoes microscopic inspection by GIA-certified gemologists to verify certificate matching.","refundProcess":"Refunds are credited back to the original payment method after gemological inspection approval.","refundTiming":"Processed within 3-5 business days of inspection completion.","shippingResponsibility":"AethelCarats provides complimentary insured return shipping labels for all domestic returns.","customJewelleryRules":"Bespoke custom items are final sale. Ring resize adjustments are covered under our Lifetime Service Guarantee.","diamondRules":"Loose diamonds must be returned with their original GIA / IGI paper certificates. Lost certificates incur a $250 laboratory replacement fee.","importantNotes":"Returns received without an RA number or after 15 days will be returned to sender."}', '{"heading":"Returns & Refund Policy","subheading":"We offer a complimentary 15-day return policy on all non-customized fine jewellery and loose diamonds.","introduction":"At AethelCarats, your complete satisfaction is paramount. If for any reason you are not completely enchanted with your purchase, you may return it within 15 days of receipt.","returnEligibility":"Items must be returned in original, unworn condition with all original certification documents, security tags intact, and luxury box packaging.","returnWindow":"15 Days from date of delivery","nonReturnableItems":"Custom CAD bespoke jewellery, engraved items, altered ring sizes beyond standard range, and damaged items.","returnProcess":"Contact concierge@aethelcarats.com to receive a fully insured prepaid FedEx shipping label and Return Authorization (RA) number.","inspectionProcess":"Every returned gemstone and diamond undergoes microscopic inspection by GIA-certified gemologists to verify certificate matching.","refundProcess":"Refunds are credited back to the original payment method after gemological inspection approval.","refundTiming":"Processed within 3-5 business days of inspection completion.","shippingResponsibility":"AethelCarats provides complimentary insured return shipping labels for all domestic returns.","customJewelleryRules":"Bespoke custom items are final sale. Ring resize adjustments are covered under our Lifetime Service Guarantee.","diamondRules":"Loose diamonds must be returned with their original GIA / IGI paper certificates. Lost certificates incur a $250 laboratory replacement fee.","importantNotes":"Returns received without an RA number or after 15 days will be returned to sender."}', 'PUBLISHED', '2026-08-10 05:22:27.593', 'System Seed', NULL, '2026-08-10 05:22:27.594', '2026-08-10 08:53:47.932');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('48acf2c7-7ffa-4065-b0bf-0f4cbd514eb8', 'Complimentary Insured Worldwide Shipping', 'shipping-delivery', '{"heading":"Complimentary Insured Worldwide Shipping","subheading":"Every AethelCarats creation is dispatched via fully insured priority express air transportation.","introduction":"We understand the value of your purchase. That is why every shipment is fully insured by Lloyds of London from our atelier vault directly to your hands.","shippingInformation":"All packages are shipped in discreet, unbranded outer packaging for security.","shippingCountries":"United States, Canada, United Kingdom, European Union, Australia, UAE, Singapore, Japan, Switzerland, Hong Kong, and 50+ countries.","processingTime":"In-stock items ship within 1-2 business days. Custom and resized orders require 5-10 crafting business days.","deliveryTime":"Domestic Overnight Express (1 Business Day). International Priority Air (2-4 Business Days).","insuranceInformation":"100% full transit insurance coverage included on every order at no extra charge.","courierInformation":"Dispatched via FedEx Priority Overnight or Malca-Amit Armored Express.","signatureRequirement":"Adult Signature Required upon delivery. Packages cannot be left unattended or diverted to secondary addresses.","shippingCharges":"Complimentary Priority Express Shipping on all orders over $500.","freeShippingRules":"All domestic US & Canada orders include complimentary FedEx Priority Overnight.","internationalShipping":"International orders ship DDP (Delivered Duty Paid) or DDU depending on country customs regulations.","customsInformation":"Customs duties and taxes are calculated transparently at checkout.","importantNotes":"You will receive an encrypted tracking code as soon as your shipment is dispatched."}', '{"heading":"Complimentary Insured Worldwide Shipping","subheading":"Every AethelCarats creation is dispatched via fully insured priority express air transportation.","introduction":"We understand the value of your purchase. That is why every shipment is fully insured by Lloyds of London from our atelier vault directly to your hands.","shippingInformation":"All packages are shipped in discreet, unbranded outer packaging for security.","shippingCountries":"United States, Canada, United Kingdom, European Union, Australia, UAE, Singapore, Japan, Switzerland, Hong Kong, and 50+ countries.","processingTime":"In-stock items ship within 1-2 business days. Custom and resized orders require 5-10 crafting business days.","deliveryTime":"Domestic Overnight Express (1 Business Day). International Priority Air (2-4 Business Days).","insuranceInformation":"100% full transit insurance coverage included on every order at no extra charge.","courierInformation":"Dispatched via FedEx Priority Overnight or Malca-Amit Armored Express.","signatureRequirement":"Adult Signature Required upon delivery. Packages cannot be left unattended or diverted to secondary addresses.","shippingCharges":"Complimentary Priority Express Shipping on all orders over $500.","freeShippingRules":"All domestic US & Canada orders include complimentary FedEx Priority Overnight.","internationalShipping":"International orders ship DDP (Delivered Duty Paid) or DDU depending on country customs regulations.","customsInformation":"Customs duties and taxes are calculated transparently at checkout.","importantNotes":"You will receive an encrypted tracking code as soon as your shipment is dispatched."}', 'PUBLISHED', '2026-08-10 05:22:27.806', 'System Seed', NULL, '2026-08-10 05:22:27.807', '2026-08-10 08:53:48.144');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('32516e57-04e4-4630-873e-1f60eb3f0172', 'Quality & Value — The AethelCarats Legacy', 'about-us', '{"heading":"Quality & Value — The AethelCarats Legacy","subheading":"Handcrafted luxury, uncompromised diamond excellence, and direct atelier pricing.","introduction":"Founded on Fifth Avenue, AethelCarats bridges master European goldsmithing traditions with modern precision diamond cutting.","brandStory":"AethelCarats was born out of a desire to eliminate bloated traditional luxury markups. By sourcing rough diamonds directly and hand-forging settings in-house, we deliver high jewellery at unprecedented value.","ourValues":"Integrity, unyielding quality, complete diamond certification transparency, and personalized client relationships.","quality":"Only the top 1% of gem-grade diamonds are selected for AethelCarats settings.","craftsmanship":"Every ring is individually hand-cast in heavy solid 18K gold or 950 Platinum, never hollowed or micro-plated.","manufacturing":"Our master goldsmiths average 20+ years of bench experience in New York and Geneva.","diamonds":"Exclusively certified by GIA (Gemological Institute of America) and IGI.","jewellery":"Elegantly proportioned silhouettes designed to maximize light performance and fire.","whyAethelCaratsJewel":"Direct diamond sourcing, bespoke CAD customization, conflict-free guarantee, and lifetime warranty."}', '{"heading":"Quality & Value — The AethelCarats Legacy","subheading":"Handcrafted luxury, uncompromised diamond excellence, and direct atelier pricing.","introduction":"Founded on Fifth Avenue, AethelCarats bridges master European goldsmithing traditions with modern precision diamond cutting.","brandStory":"AethelCarats was born out of a desire to eliminate bloated traditional luxury markups. By sourcing rough diamonds directly and hand-forging settings in-house, we deliver high jewellery at unprecedented value.","ourValues":"Integrity, unyielding quality, complete diamond certification transparency, and personalized client relationships.","quality":"Only the top 1% of gem-grade diamonds are selected for AethelCarats settings.","craftsmanship":"Every ring is individually hand-cast in heavy solid 18K gold or 950 Platinum, never hollowed or micro-plated.","manufacturing":"Our master goldsmiths average 20+ years of bench experience in New York and Geneva.","diamonds":"Exclusively certified by GIA (Gemological Institute of America) and IGI.","jewellery":"Elegantly proportioned silhouettes designed to maximize light performance and fire.","whyAethelCaratsJewel":"Direct diamond sourcing, bespoke CAD customization, conflict-free guarantee, and lifetime warranty."}', 'PUBLISHED', '2026-08-10 05:22:29.048', 'System Seed', NULL, '2026-08-10 05:22:29.049', '2026-08-10 08:53:49.206');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('b0dbf025-8c80-4ce5-b282-198bc513fdcd', 'The Diamond Vault', 'diamonds', '{"heading":"The Diamond Vault","subheading":"Search over 10,000 ethically sourced GIA & IGI certified natural and lab-grown diamonds.","introduction":"Use our advanced diamond filter to select by carat, shape, color, clarity, cut grade, and certification laboratory.","filterDescription":"Filter by exact millimeter dimensions, table/depth ratios, polish, symmetry, and fluorescence.","diamondInfo":"Every diamond is individually inspected by our in-house gemologists to ensure ideal light performance.","certificationInformation":"100% GIA or IGI certified. Digital laboratory reports viewable online.","buttonText":"Explore Loose Diamonds","buttonUrl":"/diamonds"}', '{"heading":"The Diamond Vault","subheading":"Search over 10,000 ethically sourced GIA & IGI certified natural and lab-grown diamonds.","introduction":"Use our advanced diamond filter to select by carat, shape, color, clarity, cut grade, and certification laboratory.","filterDescription":"Filter by exact millimeter dimensions, table/depth ratios, polish, symmetry, and fluorescence.","diamondInfo":"Every diamond is individually inspected by our in-house gemologists to ensure ideal light performance.","certificationInformation":"100% GIA or IGI certified. Digital laboratory reports viewable online.","buttonText":"Explore Loose Diamonds","buttonUrl":"/diamonds"}', 'PUBLISHED', '2026-08-10 05:22:30.11', 'System Seed', NULL, '2026-08-10 05:22:30.111', '2026-08-10 08:53:50.266');
INSERT IGNORE INTO `Page` (`id`, `title`, `slug`, `content`, `draftContent`, `status`, `lastPublishedAt`, `publishedBy`, `lastModifiedBy`, `createdAt`, `updatedAt`) VALUES ('53fd15ef-36dc-4be3-b94b-8ee57ff257eb', 'Terms of Service', 'terms-of-service', '{"heading":"Terms of Service","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Acceptance of Terms</h2>\\\\n      <p>By accessing AethelCarats (\\\\"the Website\\\\") or placing an order, you agree to be bound by these Terms of Service and all applicable luxury retail laws.</p>\\\\n      <h2>2. Diamond Pricing & Availability</h2>\\\\n      <p>All loose diamond and fine jewellery prices are subject to real-time market market availability. We reserve the right to correct typographical pricing errors.</p>\\\\n      <h2>3. Intellectual Property</h2>\\\\n      <p>All 3D CAD renders, product designs, website photography, logos, and copywriting are the exclusive property of AethelCarats Atelier.</p>\\\\n      <h2>4. Order Acceptance & Cancellations</h2>\\\\n      <p>Order receipt confirmation does not constitute final order acceptance. We reserve the right to decline orders subject to fraud verification.</p>\\\\n    "}', '{"heading":"Terms of Service","lastUpdated":"August 09, 2026","content":"\\\\n      <h2>1. Acceptance of Terms</h2>\\\\n      <p>By accessing AethelCarats (\\\\"the Website\\\\") or placing an order, you agree to be bound by these Terms of Service and all applicable luxury retail laws.</p>\\\\n      <h2>2. Diamond Pricing & Availability</h2>\\\\n      <p>All loose diamond and fine jewellery prices are subject to real-time market market availability. We reserve the right to correct typographical pricing errors.</p>\\\\n      <h2>3. Intellectual Property</h2>\\\\n      <p>All 3D CAD renders, product designs, website photography, logos, and copywriting are the exclusive property of AethelCarats Atelier.</p>\\\\n      <h2>4. Order Acceptance & Cancellations</h2>\\\\n      <p>Order receipt confirmation does not constitute final order acceptance. We reserve the right to decline orders subject to fraud verification.</p>\\\\n    "}', 'PUBLISHED', '2026-08-10 05:22:32.026', 'System Seed', NULL, '2026-08-10 05:22:32.027', '2026-08-10 08:53:52.174');
