INSERT IGNORE INTO `PageSection` (`id`, `pageId`, `blockType`, `position`, `content`, `isVisible`) VALUES ('92f1307f-be38-470e-8510-b69814307cfb', '6b50a759-545c-49a1-87c4-20c3dc2f4c7c', 'HERO', 1, '{"eyebrow":"THE SIGNATURE COLLECTION 2026","heading":"Handcrafted Elegance & Exceptional Diamonds","description":"Immerse yourself in world-class craftsmanship, ethically sourced diamonds, and timeless bespoke creations.","desktopImage":"/assets/gem_rings_cat.png","mobileImage":"/assets/gem_rings_cat.png","tabletImage":"/assets/gem_rings_cat.png","button1Text":"EXPLORE RINGS","button1Link":"/rings","button2Text":"THE DIAMOND VAULT","button2Link":"/diamonds"}', 1);
