INSERT IGNORE INTO `PageSection` (`id`, `pageId`, `blockType`, `position`, `content`, `isVisible`) VALUES ('4d6bc428-33d2-4ac7-b640-72df0f9c30df', '6b50a759-545c-49a1-87c4-20c3dc2f4c7c', 'CAMPAIGN_BANNER', '3', '{"enableBanner":true,"desktopImage":"/uploads/media/img_1788873789162_h2nv4_file_0000000012748211987f375973fbb996.png","heading":"A NEW EXPRESSION OF FINE JEWELLERY","description":"Designed with intention. Crafted with precision. Made to be treasured for generations.","buttonText":"EXPLORE THE COLLECTION","buttonLink":"/collections/signature-collection","objectPosition":"center 35%","showOverlay":true,"overlayOpacity":0.45}', 1);
INSERT IGNORE INTO `PageSection` (`id`, `pageId`, `blockType`, `position`, `content`, `isVisible`) VALUES ('79df6e21-82b9-49f6-98d3-82871cad54e3', '6b50a759-545c-49a1-87c4-20c3dc2f4c7c', 'DIAMOND_SHAPES', '4', '{"eyebrow":"AUTHENTICATED LOOSE DIAMONDS","heading":"Discover Exceptional Diamond Shapes","description":"Select your ideal cut from certified GIA & IGI diamonds, ethically sourced and precision-cut for maximum fire and brilliance.","leftImage":"/assets/aethelcarats_diamonds_cat.png","shapes":[{"name":"ROUND","shape":"round","url":"/diamonds?shape=round","svg":"/assets/diamonds/Round.svg","enabled":true,"altText":"Round Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"OVAL","shape":"oval","url":"/diamonds?shape=oval","svg":"/assets/diamonds/Oval.svg","enabled":true,"altText":"Oval Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"EMERALD","shape":"emerald","url":"/diamonds?shape=emerald","svg":"/assets/diamonds/Emerald.svg","enabled":true,"altText":"Emerald Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"PRINCESS","shape":"princess","url":"/diamonds?shape=princess","svg":"/assets/diamonds/Princess.svg","enabled":true,"altText":"Princess Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"CUSHION","shape":"cushion","url":"/diamonds?shape=cushion","svg":"/assets/diamonds/Cushion.svg","enabled":true,"altText":"Cushion Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"PEAR","shape":"pear","url":"/diamonds?shape=pear","svg":"/assets/diamonds/Pear.svg","enabled":true,"altText":"Pear Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"RADIANT","shape":"radiant","url":"/diamonds?shape=radiant","svg":"/assets/diamonds/Radiant.svg","enabled":true,"altText":"Radiant Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"},{"name":"MARQUISE","shape":"marquise","url":"/diamonds?shape=marquise","svg":"/assets/diamonds/Marquise.svg","enabled":true,"altText":"Marquise Cut Diamond","desktopSize":"48px","tabletSize":"44px","mobileSize":"40px"}]}', 1);
INSERT IGNORE INTO `PageSection` (`id`, `pageId`, `blockType`, `position`, `content`, `isVisible`) VALUES ('37ea173d-6a12-46dd-86e9-24ecb2398b67', '6b50a759-545c-49a1-87c4-20c3dc2f4c7c', 'CRAFTSMANSHIP', '4', '{"heading":"Unrivalled Atelier Artistry","description":"Every AethelCarats creation undergoes meticulous hand-finishing, master CAD prototyping, and precision setting by master jewelers with decades of heritage.","image":"/assets/aethelcarats_cad_craftsmanship.png"}', 1);
INSERT IGNORE INTO `PageSection` (`id`, `pageId`, `blockType`, `position`, `content`, `isVisible`) VALUES ('e871afa8-bf6c-4537-bee1-566fa77eabc8', '6b50a759-545c-49a1-87c4-20c3dc2f4c7c', 'TESTIMONIALS', '5', '{"heading":"Words from Our Clients","testimonials":[{"quote":"The bespoke engagement ring exceeded all expectations. AethelCarats made the entire process seamless from CAD design to final delivery.","author":"Eleanor V., London"},{"quote":"The Diamond Vault gave us complete transparency and unmatched pricing on a GIA certified 2.50ct oval diamond.","author":"Marcus & Sophia, Zurich"}]}', 1);
