INSERT IGNORE INTO `ProductPageContent` (`id`, `productId`, `heroTitle`, `heroSubtitle`, `heroShortDescription`, `heroAnnouncement`, `heroBreadcrumbLabel`, `benefitsJson`, `accordionsJson`, `shippingInfoJson`, `craftsmanshipTitle`, `craftsmanshipDescription`, `sustainabilityInfo`, `manufacturingInfo`, `materialsInfo`, `certificationInfo`, `craftsmanshipImage`, `packagingHeading`, `packagingDescription`, `packagingItemsJson`, `packagingImageUrl`, `reviewsTitle`, `reviewsEnabled`, `reviewsVerifiedBadge`, `reviewsSubmissionEnabled`, `reviewsDefaultSort`, `similarItemsTitle`, `similarProductsJson`, `similarItemsEnabled`, `recentlyViewedTitle`, `recentlyViewedEnabled`, `showBenefits`, `showExperienceAccordion`, `showSpecifications`, `showCraftsmanshipSection`, `showPackagingSection`, `showReviews`, `showSimilarItems`, `showRecentlyViewed`, `createdAt`, `updatedAt`, `showBuyNowButton`, `showQuantitySelector`, `showStickyBar`) VALUES ('5b5df363-b4de-4c9b-895f-11a72f2297f3', NULL, 'Exquisite Mayfair Jewellery', 'Handcrafted luxury pieces designed for life\'s timeless moments.', 'Every creation is individually handcrafted in Mayfair by master jewelers using RJC-certified recycled precious metals and certified conflict-free diamonds.', 'Complimentary Express Insured Worldwide Shipping & 30-Day Returns', 'Fine Jewellery', '[{"id":"b-1","title":"Free Insured Delivery","description":"Dispatched in plain, unbranded security packaging.","icon":"Truck","sortOrder":0,"isActive":true},{"id":"b-2","title":"Lifetime Service Warranty","description":"Annual prong checking, sizing & professional cleaning.","icon":"ShieldCheck","sortOrder":1,"isActive":true},{"id":"b-3","title":"GIA / IGI Certification","description":"Independently certified 100% conflict-free diamonds.","icon":"Award","sortOrder":2,"isActive":true}]', '[{"id":"acc-1","title":"YOUR AETHELCARATS EXPERIENCE","content":"Experience white-glove atelier service with direct access to Mayfair master jewellers, custom CAD 3D photorealistic renderings, and 40x microscopic quality verification.","icon":"Sparkles","sortOrder":0,"isActive":true},{"id":"acc-2","title":"PRODUCT & DIAMOND SPECIFICATIONS","content":"Detailed specifications will automatically display metal purity, diamond carat weight, cut grade, color, clarity, certificate number, and exact millimeter dimensions.","icon":"Gem","sortOrder":1,"isActive":true},{"id":"acc-3","title":"CRAFTSMANSHIP & SUSTAINABILITY","content":"Crafted with 100% recycled 18K gold and fine silver certified by the Responsible Jewellery Council. Hand-set under microscopic precision with a lifetime guarantee.","icon":"Award","sortOrder":2,"isActive":true},{"id":"acc-4","title":"SHIPPING & DELIVERY","content":"Production takes 7–10 working days. Dispatched via fully insured FedEx Priority Air in unbranded outer security boxes with signature required upon delivery.","icon":"Truck","sortOrder":3,"isActive":true}]', '{"processingTime":"1–2 working days","manufacturingTime":"7–10 working days","shippingTime":"2–4 working days","deliveryTime":"7–10 working days after production","shippingMethod":"FedEx Priority Express (Fully Insured)","insuranceInfo":"100% covered from our Mayfair atelier until hand-delivered to recipient.","returnInfo":"30-Day Money Back Guarantee with complimentary return shipping.","internationalShippingInfo":"Available worldwide with customs duties & taxes handled seamlessly."}', 'Craftsmanship & Sustainability', 'We combine traditional Mayfair goldsmithing heritage with sustainable innovation. Every piece is handcrafted by master artisans to ensure uncompromised elegance and enduring quality.', '100% Recycled Precious Metals certified by the Responsible Jewellery Council (RJC).', 'Precision hand-setting under 40x microscopic magnification for optimal gem security.', 'Solid 18K Gold (Yellow, White, Rose) or 950 Platinum, nickel-free and hypoallergenic.', 'Independently graded by GIA or IGI with digital certificate verification.', '/assets/gem_rings_cat.png', 'We\'re committed to making your entire experience a pleasant one, from shopping to shipping.', 'Every item arrives in signature AethelCarats packaging. Engagement rings come in a velvet presentation box with appraisal certificate and GIA/IGI grading report.', '[{"id":"pkg-1","title":"Discreet Packaging","description":"Every order is shipped in plain, unbranded outer security boxes. No mention of AethelCarats or diamond jewelry on package exterior.","icon":"Package","sortOrder":0,"isActive":true},{"id":"pkg-2","title":"Secure and Convenient Pickup Option","description":"Hold your order for pickup at thousands of secure FedEx locations or choose insured signature delivery directly to your door.","icon":"ShieldCheck","sortOrder":1,"isActive":true},{"id":"pkg-3","title":"Free Insured Shipping & Complimentary Returns","description":"Enjoy free express delivery on every order, fully insured from our Mayfair atelier to your hands, backed by our 30-day money-back guarantee.","icon":"Truck","sortOrder":2,"isActive":true}]', '/assets/aethelcarats_ring_box.png', 'Customer Reviews & Feedback', 1, 1, 1, 'newest', 'You May Also Like', '[]', 1, 'Recently Viewed', 1, 1, 1, 1, 1, 1, 1, 1, 1, '2026-08-10 08:15:45.553', '2026-08-10 08:15:45.553', 1, 1, 1);
INSERT IGNORE INTO `Promotion` (`id`, `title`, `type`, `heading`, `subheading`, `description`, `imageUrl`, `mobileImageUrl`, `videoUrl`, `buttonText`, `buttonUrl`, `linkUrl`, `backgroundColor`, `textColor`, `startDate`, `endDate`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('f441def2-78ee-46cd-b0ac-c36aa4e8ce48', 'Grand Solitaire Hero Slide', 'HERO_SLIDE', 'THE SOLITAIRE COLLECTION', 'ETERNAL ARTISTRY & ETHICAL DIAMONDS', NULL, '/assets/aethelcarats_hero_1.png', NULL, NULL, 'DISCOVER RINGS', '/rings', NULL, NULL, NULL, NULL, NULL, 1, '0', '2026-08-09 11:05:52.951', '2026-08-09 11:05:52.951');
REPLACE INTO `RingSizeGuide` (`id`, `title`, `slug`, `status`, `heroTitle`, `heroSubtitle`, `heroImage`, `heroImagePosition`, `heroBg`, `heroCtaText`, `heroCtaUrl`, `introHeading`, `introParagraphs`, `introContent`, `infoHeading`, `infoDescription`, `chartImage`, `chartTitle`, `chartDescription`, `conversionsJson`, `sizerHeading`, `sizerDescription`, `sizerImage`, `sizerButtonText`, `sizerButtonUrl`, `measureHeading`, `measureDescription`, `measureStepsJson`, `ctaHeading`, `ctaDescription`, `ctaButtonText`, `ctaButtonUrl`, `ctaBg`, `seoTitle`, `metaDescription`, `keywords`, `canonicalUrl`, `ogTitle`, `ogDescription`, `ogImage`, `createdAt`, `updatedAt`) VALUES ('main', 'Ring Size Guide', 'find-your-ring-size', 'PUBLISHED', 'FIND YOUR PERFECT RING SIZE', 'Comprehensive AethelCarats Sizing Guide', '/assets/education/ring-sizer-hero.jpg', 'center', '#19202A', 'Request Free Ring Sizer', '#free-sizer', 'Precision Sizing for Life\'s Timeless Moments', 'At AethelCarats, a ring is a symbol of lifelong devotion crafted to fit comfortably and securely.', NULL, 'International Ring Size Conversion', 'Measure your finger diameter or convert existing ring sizes using our standardized international chart.', '/assets/education/ring-size-chart-printable.png', 'Ring Size Measurement Chart', 'Print at 100% scale to match your existing rings directly.', '[{"us":"3","uk":"F","eu":"44","diameter":"14.1","circumference":"44.2"},{"us":"4","uk":"H 1/2","eu":"46.5","diameter":"14.9","circumference":"46.8"},{"us":"5","uk":"J 1/2","eu":"49","diameter":"15.7","circumference":"49.3"},{"us":"6","uk":"L 1/2","eu":"51.5","diameter":"16.5","circumference":"51.9"},{"us":"7","uk":"N 1/2","eu":"54","diameter":"17.3","circumference":"54.4"},{"us":"8","uk":"P 1/2","eu":"56.5","diameter":"18.1","circumference":"56.9"},{"us":"9","uk":"R 1/2","eu":"59","diameter":"18.9","circumference":"59.5"},{"us":"10","uk":"T 1/2","eu":"61.5","diameter":"19.8","circumference":"62.1"},{"us":"11","uk":"V 1/2","eu":"64","diameter":"20.6","circumference":"64.6"},{"us":"12","uk":"X 1/2","eu":"66.5","diameter":"21.4","circumference":"67.2"}]', 'COMPLIMENTARY AETHELCARATS RING SIZER', 'Receive our reusable precision ring sizer delivered directly to your door with complimentary shipping.', '/assets/education/ring-sizer-tool.jpg', 'REQUEST FREE SIZER', '#request-sizer', 'HOW TO MEASURE AT HOME', 'Follow these three simple steps using a strip of paper or string.', '[{"step":1,"title":"Wrap Paper or String","description":"Wrap a paper strip comfortably around the base of your finger.","image":"/assets/education/step-1-wrap.jpg"},{"step":2,"title":"Mark Measurement Point","description":"Mark the exact point where the ends meet with a fine pen.","image":"/assets/education/step-2-mark.jpg"},{"step":3,"title":"Measure Length in Millimeters","description":"Measure the length against a ruler in mm to determine circumference.","image":"/assets/education/step-3-ruler.jpg"}]', 'NEED EXPERT SIZING ASSISTANCE?', 'Our Mayfair atelier master jewellers are available 7 days a week for personalized consultations.', 'BOOK ATELIER CONSULTATION', '/contact-us', '#19202A', 'Ring Size Guide | AethelCarats', 'Find your perfect ring size with AethelCarats comprehensive international conversion chart.', 'ring size guide, ring sizer, international ring sizes', 'https://aethelcarats.com/education/rings/find-your-ring-size', 'AethelCarats Ring Size Guide', 'Find your exact ring size using our international chart and free ring sizer tool.', '/assets/education/ring-sizer-hero.jpg', '2026-08-10 05:22:27.97', NOW());
